import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 83 After the elections","description":"学习 将来表达与安排，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 83 After the elections","description":"学习 将来表达与安排，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 将来表达与安排，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 82 Monster or fish?","link":"/life/english/new-concept/book-2/unit-04/lesson-082"},"next":{"text":"第二册：实践与进步 · Lesson 84 On strike","link":"/life/english/new-concept/book-2/unit-04/lesson-084"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 82 Monster or fish?","link":"/life/english/new-concept/book-2/unit-04/lesson-082"},"next":{"text":"第二册：实践与进步 · Lesson 84 On strike","link":"/life/english/new-concept/book-2/unit-04/lesson-084"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-083.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-083.md"}'),o={name:"life/english/new-concept/book-2/unit-04/lesson-083.md"};function l(s,e,r,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-lesson-83-after-the-elections" tabindex="-1">第二册：实践与进步 · Lesson 83 After the elections <a class="header-anchor" href="#第二册-实践与进步-·-lesson-83-after-the-elections" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 83 After the elections&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>选举后的承诺需要落实时间，支持者与怀疑者可能并存；练习将来完成和间接引语。本课的语言观察是：will have published 表承诺在截止点前完成发布；will discuss 只表示计划讨论。报告承诺时必须保留谁承诺的，不把其当成已发生事实。完成学习后，请写三句公共承诺记录，包含承诺者、截止时间和未明确的问题。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>election</td><td>/ɪˈlekʃən/</td><td>n.</td><td>选举</td><td>a local election</td></tr><tr><td>vote</td><td>/vəʊt/</td><td>v.</td><td>投票</td><td>vote for a candidate</td></tr><tr><td>candidate</td><td>/ˈkændɪdət/</td><td>n.</td><td>候选人</td><td>a local candidate</td></tr><tr><td>support</td><td>/səˈpɔːt/</td><td>n.</td><td>支持</td><td>public support</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>vote for — 投票支持某人或方案</li><li>keep a promise — 履行承诺</li></ul><h2 id="语法讲解-将来表达与安排" tabindex="-1">语法讲解：将来表达与安排 <a class="header-anchor" href="#语法讲解-将来表达与安排" aria-label="Permalink to &quot;语法讲解：将来表达与安排&quot;">​</a></h2><p>will 加动词原形可表达预测、意愿或当场决定；be going to 常表达已有打算或基于眼前证据的判断；现在进行时可描述已经落实的个人安排。表示时刻表也可用一般现在时。它们并不是严格的一对一中文翻译。时间和条件状语从句谈将来时，通常用现在时配合主句的将来表达，而不是把每个动词都加上 will。本课应用：will have published 表承诺在截止点前完成发布；will discuss 只表示计划讨论。报告承诺时必须保留谁承诺的，不把其当成已发生事实。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The candidate promised that the council would publish a plan by June.</p></blockquote><p>候选人承诺，议会会在六月前公布一项计划。</p><p>promised 明确信息来源，would publish 是过去视角的将来，by June 表截止时间。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>by June 与 in June 不同：前者指最迟到该时间，后者指在该月内。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照 promised 与 published，重读 by June，避免把截止理解为持续时间。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The candidate promised that the council would publish a plan by June. Residents asked how the work would be funded. The candidate said the details were still being prepared.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句公共承诺记录，包含承诺者、截止时间和未明确的问题。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：promised 明确信息来源，would publish 是过去视角的将来，by June 表截止时间。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：by June 与 in June 不同：前者指最迟到该时间，后者指在该月内。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 by/in：The deadline is June; the plan must appear ___ June.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> by</p><p><strong>解析：</strong> by 标记完成期限。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>资金细节已经公布了吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> No. They were still being prepared.</p><p><strong>解析：</strong> still being prepared 说明仍在准备，不能当作公开文件。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“投票支持这个方案”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> vote for the plan</p><p><strong>解析：</strong> vote for 引出支持对象，与 vote against 相反。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：将来表达与安排。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-082">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-084">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(o,[["render",l]]);export{u as __pageData,b as default};
